Write-Host "`n>>> [2/7] Harvesting & MX-Verifying 28 Real YouTube/Video/Podcast/Creator Agency Leads..." -ForegroundColor Cyan
python "$ProjectDir\Modules\b2b_public_lead_harvester.py"

Write-Host "`n>>> [3/7] Running B2B CRM Bulk Import, Proposal PDF Factory & M.O.N.D.A.Y./Ollama Outreach..." -ForegroundColor Cyan
if ($SendLiveOutreach) {
    Write-Host "  [MODE] LIVE GMAIL API DISPATCH ACTIVE (Daily Cap: $DailyEmailCap)" -ForegroundColor Green
    python "$ProjectDir\Modules\b2b_client_acquisition_engine.py" --csv "$ProjectDir\data\b2b_prospects_verified.csv" --live --cap $DailyEmailCap
} else {
    Write-Host "  [MODE] STAGING + PROPOSAL PDF BUILD (Pass -SendLiveOutreach to dispatch live Gmail API)" -ForegroundColor Yellow
    python "$ProjectDir\Modules\b2b_client_acquisition_engine.py" --csv "$ProjectDir\data\b2b_prospects_verified.csv" --cap $DailyEmailCap
}

Write-Host "`n>>> [4/7] Publishing Live YouTube Conversion Comments, 6-Stream Promo Pack & Command Center..." -ForegroundColor Cyan
python "$ProjectDir\Modules\multi_stream_promo_publisher.py"
if (Test-Path "$ProjectDir\Modules\autonomous_learning_swarm.py") { python "$ProjectDir\Modules\autonomous_learning_swarm.py" }
if (Test-Path "$ProjectDir\Modules\revenue_velocity_engine.py") { python "$ProjectDir\Modules\revenue_velocity_engine.py" }

Write-Host "`n>>> [5/7] Registering Recurring Lead-Refresh & Daily Multi-Stream Promo Tasks..." -ForegroundColor Cyan
try {
    $set = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -StartWhenAvailable
    $actH = New-ScheduledTaskAction -Execute "python.exe" -Argument "`"$ProjectDir\Modules\b2b_public_lead_harvester.py`"" -WorkingDirectory $ProjectDir
    Register-ScheduledTask -TaskName "OracleSystems_LeadHarvester_Weekly" -Action $actH -Trigger (New-ScheduledTaskTrigger -Weekly -DaysOfWeek Monday -At 8:00AM) -Settings $set -Force | Out-Null

    $actP = New-ScheduledTaskAction -Execute "python.exe" -Argument "`"$ProjectDir\Modules\multi_stream_promo_publisher.py`"" -WorkingDirectory $ProjectDir
    Register-ScheduledTask -TaskName "OracleSystems_MultiStreamPromo_Daily" -Action $actP -Trigger (New-ScheduledTaskTrigger -Daily -At 12:00PM) -Settings $set -Force | Out-Null
    Write-Host "[TASKS PASS] Registered OracleSystems_LeadHarvester_Weekly (Mon 8AM) + OracleSystems_MultiStreamPromo_Daily (12PM)" -ForegroundColor Green
} catch {
    Write-Host "[TASKS NOTE] $($_.Exception.Message)" -ForegroundColor Yellow
}

Write-Host "`n>>> [6/7] Mirroring Leads, Proposals & Promo Reports to Google Drive + GitHub..." -ForegroundColor Cyan
foreach ($rep in @("Verified_Agency_Leads_Master.md","Live_Revenue_Promo_Broadcast.md","Revenue_Velocity_Action_Plan.md")) {
    $src = Join-Path "$ProjectDir\reports" $rep
    if (Test-Path $src) { Copy-Item $src (Join-Path "$ProjectDir\Oracle_Audit_2026" $rep) -Force -ErrorAction SilentlyContinue }
}
if (Get-Command rclone -ErrorAction SilentlyContinue) {
    rclone copy "$ProjectDir\Oracle_Audit_2026" "gdrive:Oracle_Audit_2026" --update --bind 0.0.0.0
    if ($LASTEXITCODE -eq 0) { Write-Host "[DRIVE SYNC PASS] Mirrored Lead Directory & Promo Broadcast over IPv4." -ForegroundColor Green }
}
if (Test-Path "$ProjectDir\optimize_ram_and_boot.ps1") { & "$ProjectDir\optimize_ram_and_boot.ps1" -TrimNow }

$SafeFiles = @(
    "Deploy_LeadGen_Promo_Revenue_Engine.ps1",
    "Modules/b2b_public_lead_harvester.py",
    "Modules/multi_stream_promo_publisher.py"
)
foreach ($sf in $SafeFiles) { if (Test-Path "$ProjectDir\$sf") { git add -- $sf } }
if (git diff --cached --name-only) {
    git commit -m "Sophisticated B2B Lead Harvester (28 Verified Agencies + MX Check), Live YouTube Conversion Commenter & 6-Stream Revenue Command Center"
    $br = (git rev-parse --abbrev-ref HEAD).Trim()
    git push -u origin $br
    if ($LASTEXITCODE -eq 0) { Write-Host "[GITHUB PASS] Pushed cleanly to origin/$br!" -ForegroundColor Green }
}

Write-Host "`n>>> [7/7] Opening Interactive Oracle Revenue & Lead Command Center..." -ForegroundColor Cyan
$hub = "$ProjectDir\reports\Oracle_Revenue_Lead_Command_Center.html"
if (Test-Path $hub) { Start-Process $hub }

Write-Host "`n[ENGINE COMPLETE] Verified leads populated, Proposal PDFs generated, live YouTube promo comments posted & Command Center opened!" -ForegroundColor Green
if (-not $SendLiveOutreach) {
    Write-Host "[LAUNCH LIVE B2B OUTREACH] Review deliverables\b2b_outbox\ then send your first 10 verified agency emails:" -ForegroundColor Yellow
    Write-Host "  powershell -NoProfile -ExecutionPolicy Bypass -File .\Deploy_LeadGen_Promo_Revenue_Engine.ps1 -SendLiveOutreach -DailyEmailCap 10" -ForegroundColor Yellow
}
